def test_consecutive_blank_lines_collapsed():
    out, _ = _condense_plan(NASTY)
    # 代码块外不应出现「连续 2 个以上空行」（按行判断，跳过 fenced code block 内部）
    in_code = False
    run = 0
    for ln in out.split("\n"):
        if ln.strip().startswith("```"):
            in_code = not in_code
            run = 0
            continue
        if in_code:
            continue
        if ln == "":
            run += 1
            assert run <= 1, "代码块外出现连续空行"
        else:
            run = 0

